def gallery():
    foto = [("flotta-schierata", "ga.c1"), ("daf-piazzale", "ga.c2"),
            ("rimorchio-kogel", "ga.c3"), ("rimorchio-krone", "ga.c4"),
            ("ribaltabile", "ga.c5"), ("ribaltabili-toscana", "ga.c6"),
            ("imbarco", "ga.c7"), ("nave-grimaldi", "ga.c8"),
            ("aeroporto", "ga.c9")]
    figs = "\n".join(
        "        " + figura(n, sizes="(min-width:900px) 33vw, 100vw", didascalia=k,
                            classe="rivela", alt_t=k).replace("<figure", f'<figure data-ritardo="{i % 3}"', 1)
        for i, (n, k) in enumerate(foto))
    return f'''  <section>
    <div class="wrap">
      <p class="nota-vuoto" style="margin:0 0 var(--s2)" data-t="ga.vuoto"></p>
      <p class="guida nota-gallery" data-t="ga.intro"></p>
      <p class="guida nota-gallery" style="margin-top:var(--s3)" data-t="ga.testo"></p>
      <div class="griglia-foto">
{figs}
      </div>
    </div>
  </section>'''


